 -- SOW
 ('business_objective', 'Engagement: Lifecycle Retention Marketing, Tier 1, custom price $6,500 per month; onboarding fee voided.', 'sow', 'Monthly | Lifecycle Retention Marketing: TIER 1 | CUSTOM PRICE: $6,500', '2027-01-15'),
 ('business_objective', 'SOW primary objectives: email acquisition (list growth), design (mobile/conversion, new master template), flows (revenue foundation), advanced segmentation, campaigns across more content pillars matching the customer journey.', 'sow', 'Primary Objectives — Email Acquisition; Design; Flows; Segmentation; Campaigns', '2027-01-15'),
 ('business_objective', 'The SOW states no revenue target; the figures from the Sept 17 call ($200k/month, $250k additional, 20% = $2M/year) are not contractual.', 'sow', 'No revenue commitment appears in the SERVICES + FEE SUMMARY', '2027-01-15'),
 ('constraints_rules', 'Month 1 scope: flow rebuilds and foundational setup; campaign calendar for the next month is established at end of month 1.', 'sow', 'Month 1: Flow Rebuilds, foundational setup, end of month establish campaign calendar for next month', '2026-11-15'),
 ('constraints_rules', 'Month 2+ scope: 2–3 campaigns per week; A/B test one flow per month on subject lines, copy, or offer.', 'sow', 'Month 2+: Campaigns 2-3 campaigns/week, A/B Test 1 Flow monthly', '2027-01-15'),
 ('constraints_rules', 'Contracted flow set: Welcome, Abandoned Checkout, Post-Purchase, Replenishment, Site Abandonment, Cross-sell/Upsell, Review Requests; Layer 2: Second purchase, Add to cart, Back in stock, VIP, Sunset; segmentation leads → first-time → repeat → lapsed.', 'sow', 'Email Marketing Flows row', '2027-01-15'),
 ('constraints_rules', 'Contracted foundation: Klaviyo–Shopify integration, UTM tracking, advanced segmentation, base templates (desktop, mobile, dark mode), customer avatar research, pop-up forms with better incentives (e.g. gift with purchase vs discounts).', 'sow', 'Email Marketing Foundation row', '2027-01-15'),
 ('constraints_rules', 'Contracted reporting: retention-focused (RPE, LTV, churn, campaign vs flow attribution) with biweekly strategy meetings.', 'sow', 'Analytics & Reporting row', '2027-01-15'),
 ('constraints_rules', 'SMS is in scope for product drops, restocks, and high-urgency events, integrated with the email calendar.', 'sow', 'Integration of SMS for product drops, restocks, and high-urgency events', '2027-01-15'),
 ('offers_discounts', 'SOW guidance: prefer gift-with-purchase style incentives over discounts for capture; reduce reliance on discounts.', 'sow', 'better incentives (e.g., gift with purchase vs. discounts) ... reducing reliance on discounts', '2027-01-15'),
