 ('products_launches', 'Live catalog on atrakt.com: D-BLOAT ($29.99, powder, 3 variants), D-BLOAT LYTE ($29.99), DEBLOAT PROTOCOL bundle ($49.99), B-CLEAR ($29.99, capsules), C-VOLUME ($29.99), U-GLOW ($29.99, gummies), Z-MODE sleep gummies ($29.99), HAIR + SKIN PROTOCOL bundle ($49.99), D-BLOAT and B-CLEAR guides ($14.99), Shipping Protection ($1.99–2.42).', 'site', 'products.json 2026-10-08', '2026-11-08'),
 ('products_launches', 'Z-MODE (the "sleep gummy") is live on the site: magnesium glycinate 100 mg, L-theanine 200 mg, GABA 150 mg, lemon balm 100 mg; no melatonin.', 'site', 'Z-MODE product page', '2026-11-08'),
 -- Claims list: product by product. Pattern: allowed structure/function language taken from the site; prohibited = disease/drug framing.
 ('claims_compliance', 'CLAIMS FRAMEWORK (generic, drafted from site copy; needs compliance review): use structure/function language only ("supports", "helps maintain", "promotes"); never claim to treat, cure, prevent, or diagnose any disease or condition (acne, hair loss, insomnia, edema); no before/after outcome guarantees; carry the FDA disclaimer wherever a claim appears; products labelled 18+.', 'site', 'Derived from product pages; FDA disclaimer text was not detected in the page copy fetched on 2026-10-08 — verify it is present in the footer/labels', '2027-01-15'),
 ('claims_compliance', 'D-BLOAT allowed: "reduce bloating and water retention", "support healthy fluid balance and digestion", "feel lighter". Ingredients: vitamin C 245 mg, magnesium 100 mg, potassium 425 mg (chloride form), chloride 448 mg, dandelion root 375 mg, nettle leaf 175 mg, hibiscus 175 mg, juniper berry 100 mg, horsetail 200 mg. Avoid: "diuretic" as a drug claim, "flush toxins", weight-loss claims, "facial definition" as a guaranteed result.', 'site', 'D-BLOAT product page', '2027-01-15'),
 ('claims_compliance', 'D-BLOAT LYTE allowed: "daily electrolyte powder", "supports hydration and healthy fluid balance", "helps counter excess dietary sodium", "supports digestion". Ingredients: vitamin C 250 mg, potassium 1,000 mg, sodium 150 mg, magnesium 75 mg, dandelion root 200 mg, digestive enzymes. Avoid: comparisons that name competitors (coconut water brands, Liquid IV) in client-facing copy unless approved.', 'site', 'D-BLOAT LYTE product page', '2027-01-15'),
 ('claims_compliance', 'Z-MODE allowed: "supports deeper, more restorative sleep", "helps calm the mind and relax the body", "melatonin-free". Avoid: "treats insomnia", "sedative", sleep-duration guarantees.', 'site', 'Z-MODE product page', '2027-01-15'),
 ('claims_compliance', 'C-VOLUME allowed: "supports stronger, fuller-looking hair", "helps reduce shedding", "supports healthy hair growth", "supports healthy DHT levels". Ingredients: saw palmetto 160 mg, pumpkin seed 100 mg, L-cysteine 75 mg, bamboo (silica) 50 mg, grape seed 75 mg. Avoid: "regrows hair", "treats hair loss / alopecia", "DHT blocker" as a drug claim.', 'site', 'C-VOLUME product page', '2027-01-15'),
 ('claims_compliance', 'U-GLOW allowed: "supports natural radiance", "supports even skin tone", "antioxidant support". Ingredients: lycopene 30.9 mg, astaxanthin 12.7 mg, beta-carotene 975 mcg, vitamin E 84.4 mg. Avoid: "tanning pill", "sun protection / replaces sunscreen", "reduces fine lines" as a drug claim.', 'site', 'U-GLOW product page', '2027-01-15'),
 ('claims_compliance', 'B-CLEAR allowed: "supports clear, balanced skin", "helps regulate oil production", "supports the skin barrier". Ingredients: vitamin A 1,200 mcg, niacinamide 300 mg, pantothenic acid 300 mg, zinc 18 mg, chromium 250 mcg. Avoid: "treats acne", "reduces acne severity" (acne is a disease claim), "antibacterial", "clears breakouts in X days".', 'site', 'B-CLEAR product page — the page itself says "reduce acne severity", which is a disease claim; flag for the client', '2027-01-15'),
 ('claims_compliance', 'Bundles (DEBLOAT PROTOCOL, HAIR + SKIN PROTOCOL) inherit each component''s allowed claims; describe as "routine" or "protocol", not "treatment".', 'site', 'Bundle product pages', '2027-01-15')
) v(cat, stmt, src, quote, due);
